"""Write docs/baseline.md: sha256 of every Pack archive + how FS3Bin.dat.bak (original set) differs from FS3Bin.dat (patched set)."""
import os, sys, hashlib, collections, re
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fszip
game = sys.argv[1]; P = f'{game}/Pack'
sha = lambda b: hashlib.sha256(b).hexdigest()
L = ['# Baseline (reference "original" set)', '',
     'Generated by `tools/baseline.py` from `work/fs3-copy/Pack`. **Original set** = all Pack files as installed, except `FS3Bin.dat` is replaced by `FS3Bin.dat.bak` (`--set original`, the default of every tool). **Patched set** = as installed (`--set patched`).', '',
     '## Archive hashes (sha256, mtime)', '', '| file | bytes | sha256 | mtime |', '|---|---|---|---|']
for n in sorted(os.listdir(P)):
    b = open(f'{P}/{n}', 'rb').read(); import time
    L.append(f'| {n} | {len(b):,} | `{sha(b)}` | {time.strftime("%Y-%m-%d %H:%M", time.localtime(os.path.getmtime(f"{P}/{n}")))} |')
L += ['', '**Caveat [V/?]:** Steam-stock archives carry mtime 2024-08-18. `FS3Bin.dat.bak` (2026-08-25), `FS3Bin.dat` (2026-08-27) and `SP_FS3.pak` (2026-08-25) do not, so `.bak` is a user-made copy; that it is byte-pristine Steam content is **unverified**. `SP_FS3.pk.pak` (stock mtime) is byte-identical to `SP_FS3.pak`, so `SP_FS3.pak` was merely re-written. To prove `.bak` pristine: Steam > Properties > Installed Files > Verify integrity on a clean copy, then compare hashes above.', '']
o = fszip.open_fszip(f'{P}/FS3Bin.dat.bak'); n = fszip.open_fszip(f'{P}/FS3Bin.dat')
ho = {i.filename: sha(o.read(i)) for i in o.infolist() if not i.is_dir()}; hn = {i.filename: sha(n.read(i)) for i in n.infolist() if not i.is_dir()}
ch = sorted(f for f in ho if f in hn and ho[f] != hn[f])
grp = collections.Counter(re.sub(r'\d+', 'N', f) for f in ch)
L += ['## FS3Bin.dat.bak (original) vs FS3Bin.dat (patched)', '', f'Same member list: {set(ho)==set(hn)} ({len(ho)} files). Changed members: **{len(ch)}** of {len(ho)}.', '', '| pattern | changed |', '|---|---|']
L += [f'| `{k}` | {v} |' for k, v in grp.most_common()]
L += ['', '### Non-dialog changed members (sha256 original -> patched)', '']
L += [f'* `{f}` `{ho[f][:16]}` -> `{hn[f][:16]}`' for f in ch if not re.search(r'/(Auto|Dia)\d+\.bin$', f, re.I)]
open(f'{game}/../../../../docs/baseline.md' if False else sys.argv[2], 'w', encoding='utf-8').write('\n'.join(L) + '\n')
print('\n'.join(L[-12:]))
